import type { FullSchema, TableName } from './Table'
import type { TypeOf } from './Column'
import type { FilterIn } from '../util'

type MandatoryColumns<T extends TableName> = Required<FilterIn<FullSchema<T>, { mandatory: true }>>

export type Data<T extends TableName> = {
    [C in keyof (Partial<FullSchema<T>> & MandatoryColumns<T>)]: C extends keyof FullSchema<T>
        ? TypeOf<FullSchema<T>[C]>
        : never
}

export type Record<T extends TableName = TableName> = Now.Internal.WithID<
    {
        /** The table to which the record belongs. */
        table: T
        /** Fields and their values in the table. */
        data: Data<T>
    } & Now.Internal.Meta
>

/**
 * Create a record in any table. This is a low-level function typically used as
 * a fallback when the specific record type or metadata does not have its own
 * dedicated API. When possible, prefer using other, dedicated APIs to generate
 * metadata as those APIs will often have better type safety and will be easier
 * to use.
 *
 * @see https://docs.servicenow.com/csh?topicname=record-api-now-ts.html&version=latest
 *
 * @param record - an object containing the following properties:
 *   * **$id** - unique id for the record, typically using `Now.ID["value"]`
 *   * **table** - the name of the table to which the record belongs
 *   * **data** - fields and their values in the table
 */
export function Record<const T extends TableName, const R extends Record<T>>(record: R & Record<T>) {
    return record as R
}
